# The five system presets (change map-styles-library, #542). Their Mapbox style ids used to
# be settings; the Paper ids are read from the environment once here so an instance that
# had overridden them keeps its styles, and the production ids are the defaults.
MAPBOX_ATTRIBUTION = ('&copy; <a href="https://www.mapbox.com/about/maps/">Mapbox</a> '
                      '&copy; <a href="http://osm.org/copyright">OpenStreetMap</a>')
ESRI_URL = 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}'
PRESETS = (
    # key, name, base, provider, mapbox_style_id / tile_url, static_style, attribution, max_zoom, settings
    ('streets', 'Streets', 'mapbox/streets-v12', 'mapbox', 'mapbox/streets-v12', '', MAPBOX_ATTRIBUTION, 23, {}),
    ('satellite', 'Satellite', '', 'xyz', ESRI_URL, 'mapbox/satellite-streets-v12', '&copy; Esri', 19, {}),
    ('topo', 'Topo', '', 'mapbox', 'mapbox/outdoors-v12', '', MAPBOX_ATTRIBUTION, 22, {}),
    ('paper', 'Paper A', 'mapbox/streets-v12', 'mapbox',
     os.environ.get('MAPBOX_PAPER_STYLE', 'artemkonuchov/cmw4ul8hj00qw01r19ensc484'), '', MAPBOX_ATTRIBUTION, 22,
     'scripts/map_styles/paper_a.json'),
    ('paper_b', 'Paper B', 'mapbox/streets-v12', 'mapbox',
     os.environ.get('MAPBOX_PAPER_B_STYLE', 'artemkonuchov/cmw4v89eu00xu01s8hcrt5iqv'), '', MAPBOX_ATTRIBUTION, 22,
     'scripts/map_styles/paper_b.json'),
)


def _settings_of(spec):
    """The settings document a preset was built from: the script's file when there is one."""
    if isinstance(spec, dict):
        return spec
    path = os.path.join(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))), spec)
    try:
        with open(path) as handle:
            return json.load(handle)
    except OSError:
        return {}


def seed_presets(apps, schema_editor):
    MapStyle = apps.get_model('survey', 'MapStyle')
    MapStyleVersion = apps.get_model('survey', 'MapStyleVersion')
    for key, name, base, provider, ref, static, attribution, max_zoom, spec in PRESETS:
        style, _ = MapStyle.objects.get_or_create(organization=None, key=key, defaults={'name': name, 'base': base})
        if not style.versions.exists():
            MapStyleVersion.objects.create(
                style=style, number=1, settings=_settings_of(spec), provider=provider,
                mapbox_style_id=ref if provider == 'mapbox' else '',
                tile_url=ref if provider == 'xyz' else '',
                static_style=static, attribution=attribution, max_zoom=max_zoom, status='ready')


def unseed_presets(apps, schema_editor):
    MapStyle = apps.get_model('survey', 'MapStyle')
    MapStyle.objects.filter(organization=None, key__in=[p[0] for p in PRESETS]).delete()


